#!/usr/bin/env bash
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Deployed-source tests always exercise the portable repository fixture.
# Set SDO_DRIFT_SEED explicitly to also check a full deployed hotel seed.

(
    cd "$root/sdo/operator/runtime"
    go test -run '^(TestPendingDriftJoinsIncidentBeforeVerifiedClosure|TestPendingDriftPreventsVerificationWhenPeerIsUnresolved|TestLearningRepairAtThresholdOneDispatchesFastPathWithoutResponder|TestLearningCreditRequiresSuccessfulOutcomeAndOriginalProgramRevision|TestLearningEvidenceRejectsUnvalidatedSyntheticAndMismatchedCaptures|TestLearningCreditCannotEraseSubsequentFastPathFailure|TestWatchEventProgramMatchesOwnedServiceBeforeSweep|TestWatchEventProgramMatchesUnownedServiceBeforeSweep|TestWatchEventProgramsUseHintOnceForOwnedAndUnownedChanges|TestWatchEventTransientMidRolloutProgramNeverFires|TestWatchEventRepairQueuesNothingAndSweepClearsLearnedIncident|TestWatchEventUnownedChangeWithoutProgramMatchIsQuiet|TestWatchEventPendingBindingsSurviveRestartIndependently|TestProgramSweepUsesDefaultTimedConfirmation|TestRunPreservesStateChangesAcrossObservationBarrier|TestRunPreservesLatentFaultAcrossObservationBarrier|TestHermeticFastloopRealGoGate|TestHermeticReflectionLearnsThenIdenticalRecurrenceSkipsResponder|TestReadmeOnlyVerifiedReflectionIsRejectedAndRetried|TestFailedGlobalClosureCanLearnControllerAllClearRepair|TestHermeticFakeConfigMapEnforcesProductionLimit|TestRegisteredReflectionWorkerRejectsOversizedResultBeforeCommit|TestHermeticResponderProgramReuseThroughRealToolTransport|TestHermeticAcceptedSourceAfterMemoryCommit|TestAcceptedSourceRenderFailureIsObjectScoped|TestAcceptedSourceDoesNotReuseImagesAcrossSourceChange|TestControllerAdoptsAvailableObjectsWithExplicitRenderGap|TestGitPlanSourceUsesOnlyDeployedManifestSet|TestGitPlanSourceSelectsDeployedHotelSeed|TestControllerAdoptsSeededServiceThenDispatchesLaterDrift|TestUnexplainedTargetPortOpensLatentIncidentWithDriftCorpus|TestUnexplainedDriftDuringResponseAttachesToOpenIncident|TestHermeticForeignNetworkPolicyOpensLatentIncident|TestHermeticForeignNetworkPolicyInvariantRepeat|TestForeignNetworkPolicyInvariantNearMisses|TestForeignDriftNormalChurn|TestHermeticBenignDriftAcrossFastloopResetAndNextIncident|TestHermeticDriftlive4NewFaultAfterHealthyBaseline|TestRepairedDriftRecursWithoutProgramAfterRestart|TestVerifyRetainsDriftWithHealthyDetectors|TestClosureAdmittedDriftContracts|TestClosureDriftResolvedByRestoringSource|TestClosureL3I04Reduction|TestClosureDriftSourceErrorFailsClosed|TestClosureDriftRestoredFieldsIgnoreUnadmittedChanges|TestClosureDriftUsesSourceFieldsWhenReconcileIsNoop|TestSimSchedulePartialRepairCannotVerifyDrift|TestVerifyRetainedLearnedDriftRequiresEveryBinding|TestUnexplainedDriftSourceErrorNeverClears|TestTerminalDriftResponderFailureDoesNotWaitForTTL|TestCheckedBenignNoopClosesWithoutMitigationCredit|TestHermeticFourIncidentTrustedFastPathCompletesWithoutResponderJob|TestHermeticSourceReconcileLearningAndTrustAtThreeSkipsResponder|TestHermeticRoutingCaptureCompilesReplayableMitigator|TestIncidentCaptureRecordsRoutingTCPBeforeAnyProgramExists|TestRoutingCaptureHasCountAndTimeBudgets|TestRunCapturesRoutingWithoutTrafficWorkloads|TestRunStartsRoutingProberWithoutTrafficWorkloads|TestRoutingCaptureRecordsUnavailableCapabilityOnce|TestHermeticTrustedLatentDriftFastPathSkipsResponderAndReflection|TestFailedFastPathRollsBackAndDispatchesResponderWithSummary|TestGS1DeployedIdentityAndNamespaceScope|TestGS1BestMatchDeterministicWithUncoveredFindings|TestGS1TrustSurvivesProgramRevision|TestNativeBrokerSkipsReflectionAfterTrustedFastPath|TestRV4RestartMustNotBlessChangedPinnedImage|TestRV4PublicationFailureMustKeepAcceptedCommit|TestRV4OldReadyReplicaMustNotCountAsCompletedRollout|TestRenderedLockRestartWithoutNamedEvidenceHasObjectGap|TestRenderedLockJobNeedsRequestedCompletions|TestRenderedLockMutableImageReferencesDoNotCreateDrift|TestRenderedLockAfterRolloutAndRestart|TestRenderedLockMissingIsEvidenceGap|TestRenderedLockPublicationWaitsForClosureAcknowledgment|TestRenderedLockPerObjectGaps|TestRenderedLockConsulGapAfterMemoryCommitKeepsReservationDrift|TestSimRenderedLockSchedule|TestClosureRetainsDriftWithHealthyDetectors|TestTerminalDriftResponderFailureDoesNotWaitForTTLOrCloseHealthy|TestOrdinaryDriftAdmissionBudgetsBatchingAndNewKeyPriority)$' -count=1 .
)

cd "$root"
uv run --extra test pytest -q -p no:tach \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_hermetic_run.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_loop.py \
    tests/unit/benchmarks/sregym/fastloop/test_sdo3_descriptions.py \
    tests/unit/benchmarks/sregym/fastloop/test_sdo3_s3a_contracts.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_composite.py::test_failed_composite_resets_only_after_verified_harness_recovery \
    tests/unit/benchmarks/sregym/adapter/test_native_persistent_ops.py::test_reset_stage_syncs_accepted_pvc_before_recreating_controller \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_reset.py::test_reset_cancels_and_awaits_workers_before_deleting_captures \
    tests/unit/benchmarks/sregym/adapter/test_scripted_drift.py \
    tests/unit/benchmarks/sregym/assurance/test_mixed10_replay.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_fault_driver.py \
    tests/unit/benchmarks/sregym/fastloop/test_scripted_image_build.py
